import type { GoldenEvent, ChainRecord } from './index.js';
import type { EvidenceRecord, StoreSnapshot } from './persistence.js';

export type VersionWrite={ref:string;record:unknown};
export type LineageWrite={id:string;parents:string[]};
export type CertificationWrite={certification_id:string;[key:string]:unknown};
export type AppendBundle={
  command_id:string;
  request_hash:string;
  event:GoldenEvent;
  evidence:EvidenceRecord[];
  versions:VersionWrite[];
  chain:ChainRecord[];
  lineage:LineageWrite[];
  certifications:CertificationWrite[];
};
export type DurableAppendResult={status:'APPENDED'|'IDEMPOTENT_REPLAY';event_id:string};
export type DurableBackup={
  format:'CLP001-Q-BACKUP-v1';
  store:StoreSnapshot;
  command_request_hashes:Array<[string,string]>;
};
export interface DurableStore{
  appendBundle(bundle:AppendBundle):Promise<DurableAppendResult>;
  backup():DurableBackup;
}
export type SqlResult<T=Record<string,unknown>>={rows:T[];rowCount?:number|null};
export interface SqlClient{
  query<T=Record<string,unknown>>(sql:string,params?:unknown[]):Promise<SqlResult<T>>;
  release():void;
}
export interface SqlPool{ connect():Promise<SqlClient>; }

import { GovernanceStore } from './persistence.js';
import { replayPersistedCase } from './adapter.js';
import { hashCanonical } from './index.js';
import type { AppendBundle, DurableAppendResult, DurableBackup, DurableStore } from './q-contract.js';

function clone<T>(v:T):T{return JSON.parse(JSON.stringify(v));}
export class ReferenceTransactionalStore implements DurableStore{
  private store:GovernanceStore;
  private commandRequestHashes=new Map<string,string>();
  private tail:Promise<void>=Promise.resolve();
  constructor(store=new GovernanceStore()){this.store=store;}

  private async locked<T>(fn:()=>Promise<T>|T):Promise<T>{
    const prev=this.tail; let release!:()=>void; this.tail=new Promise<void>(r=>{release=r;});
    await prev; try{return await fn();}finally{release();}
  }

  async appendBundle(bundle:AppendBundle):Promise<DurableAppendResult>{
    return this.locked(async()=>{
      const prior=this.commandRequestHashes.get(bundle.command_id);
      if(prior!==undefined){
        if(prior!==bundle.request_hash) throw new Error('idempotency key conflict');
        return {status:'IDEMPOTENT_REPLAY',event_id:bundle.event.event_id};
      }
      const staged=GovernanceStore.fromSnapshot(this.store.snapshot());
      for(const v of bundle.versions) staged.pinVersion(v.ref,v.record);
      for(const e of bundle.evidence) staged.appendEvidence(e);
      const eventResult=staged.appendEvent(bundle.event,bundle.command_id);
      for(const c of bundle.chain){
        if(c.event_id===bundle.event.event_id && c.event_hash!==bundle.event.event_hash) throw new Error('chain event hash mismatch');
        staged.appendChainRecord(c);
      }
      for(const n of bundle.lineage) staged.appendLineageNode(n);
      for(const c of bundle.certifications) staged.appendCertification(c);
      this.store=staged;
      this.commandRequestHashes.set(bundle.command_id,bundle.request_hash);
      return {status:eventResult.status,event_id:bundle.event.event_id};
    });
  }

  backup():DurableBackup{
    return {format:'CLP001-Q-BACKUP-v1',store:clone(this.store.snapshot()),command_request_hashes:[...this.commandRequestHashes.entries()].map(clone)};
  }
  static restore(backup:DurableBackup):ReferenceTransactionalStore{
    if(backup.format!=='CLP001-Q-BACKUP-v1') throw new Error('unsupported backup format');
    const out=new ReferenceTransactionalStore(GovernanceStore.fromSnapshot(clone(backup.store)));
    out.commandRequestHashes=new Map(backup.command_request_hashes.map(clone));
    return out;
  }
  replay(correlationId:string){return replayPersistedCase(correlationId,this.store);}
  caseState(correlationId:string){const e=this.store.eventsByCorrelation(correlationId);return e.at(-1)?.decision??null;}
  governanceSnapshot(){return this.store.snapshot();}
  backupHash(){return hashCanonical(this.backup());}
}

import { canonicalize, hashCanonical, type GoldenEvent, type ChainRecord } from './index.js';
import { GovernanceStore, type EvidenceRecord, type StoreSnapshot } from './persistence.js';
import { replayPersistedCase } from './adapter.js';
import type { AppendBundle, DurableAppendResult, DurableBackup, DurableStore, SqlPool } from './q-contract.js';

export class PgTransactionalStore implements DurableStore{
  constructor(private readonly pool:SqlPool){}
  async appendBundle(bundle:AppendBundle):Promise<DurableAppendResult>{
    const c=await this.pool.connect();
    try{
      await c.query('BEGIN ISOLATION LEVEL SERIALIZABLE');
      const existing=await c.query<{request_hash:string,result_event_id:string|null}>('SELECT request_hash,result_event_id FROM clp_commands WHERE command_id=$1 FOR UPDATE',[bundle.command_id]);
      if(existing.rows.length){
        if(existing.rows[0].request_hash!==bundle.request_hash) throw new Error('idempotency key conflict');
        await c.query('COMMIT');
        return {status:'IDEMPOTENT_REPLAY',event_id:existing.rows[0].result_event_id??bundle.event.event_id};
      }
      await c.query('INSERT INTO clp_commands(command_id,request_hash,result_event_id) VALUES($1,$2,$3)',[bundle.command_id,bundle.request_hash,bundle.event.event_id]);
      for(const v of bundle.versions){
        const h=hashCanonical(v.record);
        const r=await c.query<{canonical_hash:string}>('INSERT INTO clp_versions(version_ref,canonical_hash,payload) VALUES($1,$2,$3::jsonb) ON CONFLICT (version_ref) DO NOTHING RETURNING canonical_hash',[v.ref,h,canonicalize(v.record)]);
        if((r.rowCount??r.rows.length)===0){
          const prior=await c.query<{canonical_hash:string}>('SELECT canonical_hash FROM clp_versions WHERE version_ref=$1',[v.ref]);
          if(!prior.rows[0]||prior.rows[0].canonical_hash!==h) throw new Error('immutable version conflict');
        }
      }
      for(const e of bundle.evidence) await c.query('INSERT INTO clp_evidence(evidence_id,correlation_id,content_hash,payload) VALUES($1,$2,$3,$4::jsonb)',[e.evidence_id,bundle.event.correlation_id,e.content_hash,canonicalize(e)]);
      await c.query('INSERT INTO clp_events(event_id,correlation_id,aggregate_id,aggregate_version,event_type,decision,event_hash,payload) VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb)',[bundle.event.event_id,bundle.event.correlation_id,bundle.event.aggregate_id,bundle.event.aggregate_version,bundle.event.event_type,bundle.event.decision,bundle.event.event_hash,canonicalize(bundle.event)]);
      for(const ch of bundle.chain){
        if(ch.event_id===bundle.event.event_id&&ch.event_hash!==bundle.event.event_hash) throw new Error('chain event hash mismatch');
        await c.query('INSERT INTO clp_chain(event_id,correlation_id,ordinal,event_hash,previous_chain_hash,chain_hash) VALUES($1,$2,$3,$4,$5,$6)',[ch.event_id,bundle.event.correlation_id,ch.ordinal,ch.event_hash,ch.previous_chain_hash,ch.chain_hash]);
      }
      for(const n of bundle.lineage) await c.query('INSERT INTO clp_lineage(lineage_id,correlation_id,parents,payload) VALUES($1,$2,$3::jsonb,$4::jsonb)',[n.id,bundle.event.correlation_id,canonicalize(n.parents),canonicalize(n)]);
      for(const cert of bundle.certifications) await c.query('INSERT INTO clp_certifications(certification_id,certification_hash,payload) VALUES($1,$2,$3::jsonb)',[cert.certification_id,hashCanonical(cert),canonicalize(cert)]);
      await c.query('COMMIT');
      return {status:'APPENDED',event_id:bundle.event.event_id};
    }catch(err){ try{await c.query('ROLLBACK');}catch{} throw err; }finally{c.release();}
  }

  async caseState(correlationId:string):Promise<string|null>{
    const c=await this.pool.connect();
    try{
      const r=await c.query<{decision:string|null}>('SELECT decision FROM clp_events WHERE correlation_id=$1 ORDER BY aggregate_version DESC LIMIT 1',[correlationId]);
      return r.rows[0]?.decision ?? null;
    }finally{c.release();}
  }
  async replay(correlationId:string){
    const c=await this.pool.connect();
    try{
      const er=await c.query<{payload:GoldenEvent}>('SELECT payload FROM clp_events WHERE correlation_id=$1 ORDER BY aggregate_version',[correlationId]);
      if(!er.rows.length) throw new Error('correlation id not found');
      const events=er.rows.map(r=>r.payload);
      const evid=await c.query<{payload:EvidenceRecord}>('SELECT payload FROM clp_evidence WHERE correlation_id=$1 ORDER BY evidence_id',[correlationId]);
      const chr=await c.query<ChainRecord>('SELECT ordinal,event_id,event_hash,previous_chain_hash,chain_hash FROM clp_chain WHERE correlation_id=$1 ORDER BY ordinal',[correlationId]);
      const lin=await c.query<{payload:{id:string;parents:string[]}}>('SELECT payload FROM clp_lineage WHERE correlation_id=$1 ORDER BY lineage_id',[correlationId]);
      const refs=[...new Set(events.flatMap(e=>[...e.source_refs,...e.policy_refs]))];
      const vr=refs.length?await c.query<{version_ref:string;canonical_hash:string;payload:unknown}>('SELECT version_ref,canonical_hash,payload FROM clp_versions WHERE version_ref = ANY($1::text[])',[refs]):{rows:[]};
      const versions=Object.fromEntries(vr.rows.map(r=>[r.version_ref,r.payload]));
      const version_hashes=Object.fromEntries(vr.rows.map(r=>[r.version_ref,r.canonical_hash]));
      const snapshot:StoreSnapshot={events,evidence:evid.rows.map(r=>r.payload),versions,version_hashes,commands:[],chain:chr.rows,lineage:lin.rows.map(r=>r.payload),certifications:[]};
      return replayPersistedCase(correlationId,GovernanceStore.fromSnapshot(snapshot));
    }finally{c.release();}
  }
  backup():DurableBackup{throw new Error('PostgreSQL backup requires database-native export adapter');}
}

import { canonicalize, hashCanonical } from './index.js';
import type { DurableBackup } from './q-contract.js';
import { ReferenceTransactionalStore } from './q-reference-store.js';

export type BackupEnvelope={format:'CLP001-Q-BACKUP-ENVELOPE-v1';payload_hash:string;payload:DurableBackup};
export function encodeBackup(backup:DurableBackup):string{
  const envelope:BackupEnvelope={format:'CLP001-Q-BACKUP-ENVELOPE-v1',payload_hash:hashCanonical(backup),payload:backup};
  return canonicalize(envelope);
}
export function decodeBackup(text:string):DurableBackup{
  const env=JSON.parse(text) as BackupEnvelope;
  if(env.format!=='CLP001-Q-BACKUP-ENVELOPE-v1') throw new Error('unsupported backup envelope');
  if(hashCanonical(env.payload)!==env.payload_hash) throw new Error('backup hash mismatch');
  return env.payload;
}
export function restoreAndVerifyReplay(backup:DurableBackup,correlationId:string,expectedReplayHash:string){
  const store=ReferenceTransactionalStore.restore(backup);
  const replay=store.replay(correlationId);
  if(replay.replay_hash!==expectedReplayHash) throw new Error(`replay hash mismatch:${replay.replay_hash}`);
  return replay;
}

import type { AppendBundle, DurableAppendResult } from './q-contract.js';

type TransitionDecision={allowed:boolean;reason?:string;transition_id?:string;missing_guards?:string[]};
type TransitionAuthorizer=(policy:unknown,from:string,to:string,eventType:string,satisfiedGuards:Set<string>)=>TransitionDecision;
type EligibilityEvaluator=(worker:any,context?:{aiRecommendation?:string})=>{worker_id:string;decision:string;predicate_results:Record<string,boolean>;decision_hash:string};
export interface QDurablePort{
  appendBundle(bundle:AppendBundle):Promise<DurableAppendResult>;
  caseState(correlationId:string):string|null|Promise<string|null>;
  replay(correlationId:string):unknown|Promise<unknown>;
}
export type DurableTransitionCommand={from:string;to:string;satisfied_guards:string[];bundle:AppendBundle};
export class QKernelService{
  constructor(
    private readonly store:QDurablePort,
    private readonly transitionPolicy:unknown,
    private readonly domain:{authorizeTransition:TransitionAuthorizer;evaluateEligibility:EligibilityEvaluator}
  ){}
  async executeTransition(command:DurableTransitionCommand){
    const ev=command.bundle.event;
    const auth=this.domain.authorizeTransition(this.transitionPolicy,command.from,command.to,ev.event_type,new Set(command.satisfied_guards));
    if(!auth.allowed) throw new Error(`transition denied: ${auth.reason??'UNKNOWN'}${auth.missing_guards?.length?`:${auth.missing_guards.join(',')}`:''}`);
    const persisted=await this.store.caseState(ev.correlation_id);
    const expected=persisted??'REPORTED';
    if(command.from!==expected) throw new Error(`persisted state mismatch: expected ${expected} got ${command.from}`);
    if(ev.decision!==command.to) throw new Error(`event decision mismatch: expected ${command.to} got ${ev.decision??'null'}`);
    return this.store.appendBundle(command.bundle);
  }
  evaluateWorker(worker:any,context?:{aiRecommendation?:string}){return this.domain.evaluateEligibility(worker,context);}
  caseState(correlationId:string){return this.store.caseState(correlationId);}
  replay(correlationId:string){return this.store.replay(correlationId);}
}

import type { QKernelService } from './q-service.js';
export type TransportRequest={method:string;path:string;body?:any};
export type TransportResponse={status:number;body:any};
export function createTransportHandler(service:QKernelService){
  return async function handle(req:TransportRequest):Promise<TransportResponse>{
    try{
      if(req.method==='POST'&&req.path==='/v1/clp001/transitions') return {status:200,body:await service.executeTransition(req.body)};
      if(req.method==='POST'&&req.path==='/v1/clp001/eligibility') return {status:200,body:service.evaluateWorker(req.body.worker,req.body.context)};
      const state=req.path.match(/^\/v1\/clp001\/cases\/([^/]+)\/state$/);
      if(req.method==='GET'&&state) return {status:200,body:{correlation_id:state[1],state:await service.caseState(state[1])}};
      const replay=req.path.match(/^\/v1\/clp001\/cases\/([^/]+)\/replay$/);
      if(req.method==='GET'&&replay) return {status:200,body:await service.replay(replay[1])};
      return {status:404,body:{error:'NOT_FOUND'}};
    }catch(err){return {status:409,body:{error:err instanceof Error?err.message:String(err)}};
  };
}
